const $=id=>document.getElementById(id),stage=$('stage');
const partId=new URLSearchParams(location.search).get('part');
const captureQueue=new URLSearchParams(location.search).get('capture')==='queue';
const study=new URLSearchParams(location.search).get('study');
if(new URLSearchParams(location.search).has('embed')){
 document.body.classList.add('embed');
 const views=document.createElement('div');views.className='embed-views';
 for(const id of ['detail','whole','finished'])views.append($(id));
 stage.append(views);
}
const assetBase=partId?`./assets/study/${study?encodeURIComponent(study)+'/':''}${encodeURIComponent(partId)}/`:'./assets/';
const renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(stage.clientWidth,stage.clientHeight);renderer.setClearColor(0xecedeb);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.85;stage.prepend(renderer.domElement);
const scene=new THREE.Scene();scene.up.set(0,0,1);const camera=new THREE.PerspectiveCamera(35,stage.clientWidth/stage.clientHeight,1,15000);camera.up.set(0,0,1);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;
const env=new THREE.PMREMGenerator(renderer);const room=new RoomEnvironment();scene.environment=env.fromScene(room,.02).texture;
scene.add(new THREE.HemisphereLight(0xffffff,0x7d8177,.6));const sun=new THREE.DirectionalLight(0xffffff,2);sun.position.set(-400,-600,1100);scene.add(sun);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(12000,12000),new THREE.MeshStandardMaterial({color:0xe1e4df,roughness:.85}));floor.position.z=-855;scene.add(floor);
const machine=new THREE.Group();scene.add(machine);const groups=new Map();let data,stock,stockFrame=new THREE.Group(),fixture=new THREE.Group(),tool=new THREE.Group();scene.add(stockFrame,tool);stockFrame.add(fixture);let mode='detail',time=0,playing=true,lastMove=-100,recording=false,recordStart=0;
const materials={stock:new THREE.MeshStandardMaterial({color:0xc8ced0,metalness:.9,roughness:.33}),tool:new THREE.MeshStandardMaterial({color:0xa6a79b,metalness:.9,roughness:.24}),holder:new THREE.MeshStandardMaterial({color:0x303632,metalness:.7,roughness:.3})};
function nativeMesh(r){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(r.positions,3));g.setIndex(r.indices);g.computeVertexNormals();const props=r.appearance?.colors||{},c=props.opaque_albedo||props.metal_f0||[.65,.67,.65];const mat=new THREE.MeshStandardMaterial({color:new THREE.Color().setRGB(...c,THREE.SRGBColorSpace),metalness:props.metal_f0 ? .6 : .25,roughness:.4});const m=new THREE.Mesh(g,mat);m.name=r.path;return m;}
function cylinder(radius,height,z,mat){const m=new THREE.Mesh(new THREE.CylinderGeometry(radius,radius,height,40),mat);m.rotation.x=Math.PI/2;m.position.z=z+height/2;return m;}
let toolId;
function selectTool(id){if(id===toolId)return;toolId=id;tool.clear();const t=data.plan.tools[id];tool.add(cylinder(t.diameter_mm/2,t.flute_length_mm,0,materials.tool),cylinder(t.shaft_diameter_mm/2,t.shaft_length_mm,t.flute_length_mm,materials.tool),cylinder(t.holder_diameter_mm/2,t.holder_length_mm,t.flute_length_mm+t.shaft_length_mm,materials.holder));}
// Fit the actual remaining stock in world space, including its final B/C orientation.
function fitFinishedStock(preserveDirection=false){
 if(!stock||!data)return;
 stockFrame.updateMatrixWorld(true);
 const bounds=new THREE.Box3().setFromObject(stock);
 if(bounds.isEmpty())return;
 const sphere=bounds.getBoundingSphere(new THREE.Sphere());
 const vertical=THREE.MathUtils.degToRad(camera.fov)/2;
 const horizontal=Math.atan(Math.tan(vertical)*camera.aspect);
 const distance=Math.max(10,sphere.radius*1.18/Math.sin(Math.min(vertical,horizontal)));
 const direction=preserveDirection?camera.position.clone().sub(controls.target).normalize():new THREE.Vector3(-1,-1.4,1.1).normalize();
 controls.target.copy(sphere.center);camera.position.copy(sphere.center).addScaledVector(direction,distance);
 camera.updateProjectionMatrix();controls.update();
}
function view(which){mode=which;for(const id of ['detail','whole','finished'])$(id).classList.toggle('active',which===id);if(which==='whole'){camera.position.set(3800,-5000,3200);controls.target.set(0,250,650);}else{camera.position.set(-155,-220,190);controls.target.set(0,0,80);}for(const [name,g]of groups){const ghost=['Static:1','X-Axis:1','Y-Axis:1'].includes(name);g.visible=true;g.traverse(o=>{if(o.material){o.material.transparent=ghost;o.material.opacity=ghost?(which==='whole'?.12:.035):1;o.material.depthWrite=!ghost;}});}if(which==='finished'){time=data.duration;playing=false;$('play').textContent='Play';}controls.update();if(data)pose();if(which==='finished')fitFinishedStock();}
function matBC(b,c){const pivot=new THREE.Vector3(...data.plan.indexing.pivot_mm);const B=new THREE.Matrix4().makeTranslation(...pivot.toArray()).multiply(new THREE.Matrix4().makeRotationY(-b*Math.PI/180)).multiply(new THREE.Matrix4().makeTranslation(...pivot.clone().negate().toArray()));const BC=B.clone().multiply(new THREE.Matrix4().makeRotationZ(-c*Math.PI/180));return [B,BC];}
function applyMatrix(g,m){g.matrixAutoUpdate=false;g.matrix.copy(m);}
function updateStock(move){if(data.surfaces){const f=[...data.surfaces].reverse().find(f=>f.move<=move)||data.surfaces[0];if(lastMove===f.move)return;lastMove=f.move;const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(f.positions,3));g.setIndex(new THREE.Uint32BufferAttribute(f.indices,1));if(f.normals)g.setAttribute('normal',new THREE.Float32BufferAttribute(f.normals,3));else g.computeVertexNormals();stock.geometry.dispose();stock.geometry=g;$('percent').textContent=(100*(1-f.volume_mm3/data.surfaces[0].volume_mm3)).toFixed(1)+'%';return;}if(move===lastMove)return;lastMove=move;const {shape,initial,removed}=data;stock.field.fill(-1);let count=0;const N=stock.resolution;for(let x=0;x<shape[0];x++)for(let y=0;y<shape[1];y++)for(let z=0;z<shape[2];z++){const i=(x*shape[1]+y)*shape[2]+z;if(initial[i]&&(removed[i]<0||removed[i]>move)){stock.field[(z+1)*N*N+(y+1)*N+(x+1)]=1;count++;}}// Visualization-only binomial smoothing. The authoritative voxel masks stay unchanged.
const scratch=new Float32Array(stock.field.length);for(const stride of [1,N,N*N]){scratch.set(stock.field);for(let z=1;z<N-1;z++)for(let y=1;y<N-1;y++)for(let x=1;x<N-1;x++){const i=z*N*N+y*N+x;stock.field[i]=(scratch[i-stride]+2*scratch[i]+scratch[i+stride])/4;}}
stock.isolation=0;stock.update();$('percent').textContent=(100*(1-count/data.initial_count)).toFixed(1)+'%';}
function clock(t){return `${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
function pose(){let idx=data.trajectory.findIndex(s=>s.elapsed_seconds>=time);if(idx<0)idx=data.trajectory.length-1;const end=data.trajectory[idx],start=data.trajectory[Math.max(0,idx-1)],duration=end.elapsed_seconds-start.elapsed_seconds,u=duration?THREE.MathUtils.clamp((time-start.elapsed_seconds)/duration,0,1):1;const p=start.position.map((x,i)=>x+(end.position[i]-x)*u);const bc=start.bc_degrees.map((x,i)=>x+(end.bc_degrees[i]-x)*u);const [B,BC]=matBC(...bc);applyMatrix(groups.get('B-Axis:1'),B);applyMatrix(groups.get('C-Axis:1'),BC);applyMatrix(stockFrame,BC.clone().multiply(new THREE.Matrix4().makeTranslation(...data.plan.indexing.work_offset_mm)));selectTool(end.tool);tool.position.set(...p);tool.visible=mode!=='finished';const mount=data.plan.indexing.head_mount_mm;const xyz=p.map((x,i)=>x-mount[i]+(i===2?data.plan.indexing.gauge_length_mm:0));groups.get('X-Axis:1').position.set(xyz[0],0,0);groups.get('Y-Axis:1').position.set(xyz[0],xyz[1],0);for(const name of ['Z-Axis:1','Spindle:1'])groups.get(name).position.set(...xyz);
// Removal checkpoints are at completed move boundaries; never pre-remove material.
updateStock(u>=1?end.move:start.move);const phase=[...data.design.phases].reverse().find(x=>x.move<=end.move);$('phase').textContent=mode==='finished'?'Final simulated stock':phase?.name||'Approach billet';$('seek').value=time/data.duration*1000;$('clock').textContent=`${clock(time)} / ${clock(data.duration)}`;}
try{const [bundle,d,surfaces]=await Promise.all([fetch('./assets/umc750.json').then(r=>r.json()),fetch(partId?assetBase+'playback.json':'./assets/housing.json').then(r=>{if(!r.ok)throw Error('Housing simulation is still running. Reload when artifacts are ready.');return r.json();}),fetch(partId?assetBase+'surfaces.json':'./assets/housing-surfaces.json').then(r=>r.json())]);data=d;data.surfaces=surfaces.frames;if(surfaces.binary){const bytes=await fetch(assetBase+surfaces.binary).then(r=>r.arrayBuffer());for(const f of data.surfaces){f.positions=new Float32Array(bytes,f.offset,f.vertex_values);f.normals=new Float32Array(bytes,f.offset+f.vertex_values*4,f.vertex_values);f.indices=new Uint32Array(bytes,f.offset+f.vertex_values*8,f.index_values);}}if(partId){document.querySelector('h1').textContent=data.design.name;const shape=data.design.stock_shape;document.querySelector('.badge p').textContent=shape.kind==='cylinder'?`Ø${shape.radius*2} × ${shape.height} mm billet`:`${shape.size.join(' × ')} mm stock`;document.title=data.design.name+' · Indexed CAM';} for(const r of bundle.machine.meshes){if(!groups.has(r.group)){const g=new THREE.Group();groups.set(r.group,g);machine.add(g);}groups.get(r.group).add(nativeMesh(r));}stock=new THREE.Mesh(new THREE.BufferGeometry(),materials.stock);stockFrame.add(stock);const f=data.plan.fixtures[0],size=f.max.map((v,i)=>v-f.min[i]);const pedestal=new THREE.Mesh(new THREE.BoxGeometry(...size),new THREE.MeshStandardMaterial({color:0x525b57,metalness:.7,roughness:.3}));pedestal.position.set(...f.min.map((v,i)=>(v+f.max[i])/2));fixture.add(pedestal);$('estimate').textContent=clock(data.duration);$('status').textContent=data.result.passed?`PASS · ${data.plan.tolerance_mm} mm demo tolerance`:'Geometry verification: FAIL · see result';$('status').title=data.result.issues.map(i=>i.description).join('\n');view('detail');pose();if(captureQueue)setTimeout(()=>$('record').click(),500);}catch(e){$('error').textContent=e.message;$('phase').textContent='Preparing machining study';}
$('play').onclick=()=>{if(mode==='finished')view('detail');playing=!playing;if(time>=data.duration)time=0;$('play').textContent=playing?'Pause':'Play';};$('seek').oninput=()=>{const requestedTime=Number($('seek').value)/1000*data.duration;if(mode==='finished')view('detail');playing=false;$('play').textContent='Play';time=requestedTime;pose();};for(const id of ['detail','whole','finished'])$(id).onclick=()=>view(id);
$('record').onclick=()=>{if(recording||!data)return;recording=true;recordStart=performance.now();time=0;playing=true;view('detail');renderer.setPixelRatio(1);renderer.setSize(1920,1080,false);camera.aspect=1920/1080;camera.updateProjectionMatrix();const chunks=[],stream=renderer.domElement.captureStream(30),rec=new MediaRecorder(stream,{mimeType:'video/webm;codecs=vp9',videoBitsPerSecond:10000000});rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=async()=>{const blob=new Blob(chunks,{type:'video/webm'});const r=await fetch(partId?'/api/study-video?part='+encodeURIComponent(partId):'/api/housing-video',{method:'POST',body:blob});$('record').textContent=r.ok?'Video saved':'Video save failed';recording=false;renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(stage.clientWidth,stage.clientHeight);camera.aspect=stage.clientWidth/stage.clientHeight;camera.updateProjectionMatrix();view('finished');if(captureQueue)nextCapture();};rec.start();$('record').textContent='Recording 30 s…';setTimeout(()=>rec.stop(),30000);};
new ResizeObserver(()=>{if(recording)return;camera.aspect=stage.clientWidth/stage.clientHeight;camera.updateProjectionMatrix();renderer.setSize(stage.clientWidth,stage.clientHeight);if(mode==='finished')fitFinishedStock(true);}).observe(stage);
let previous=performance.now();function frame(now){const dt=Math.min(.1,(now-previous)/1000);previous=now;if(data&&playing){time=recording?Math.min(data.duration,(now-recordStart)/28000*data.duration):Math.min(data.duration,time+dt*data.duration/75);if(recording){const blend=THREE.MathUtils.smoothstep((now-recordStart)/1000,1,3);camera.position.lerpVectors(new THREE.Vector3(3800,-5000,3200),new THREE.Vector3(-155,-220,190),blend);controls.target.lerpVectors(new THREE.Vector3(0,250,650),new THREE.Vector3(0,0,80),blend);}pose();if(time>=data.duration){playing=false;$('play').textContent='Play';}}controls.update();renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);

async function nextCapture(){const d=await fetch('/api/study-results').then(r=>r.json());const next=d.parts.find(p=>p.playback_ready&&!p.video_captured);if(next){location.href='housing.html?part='+next.id+'&study='+encodeURIComponent(d.asset_namespace||'')+'&capture=queue';return;}if(d.parts.length===d.catalog.length&&d.parts.every(p=>p.video_captured||p.status==='incomplete')){location.href='study.html';return;}$('record').textContent='Waiting for next verified part…';setTimeout(nextCapture,3000);}
